import re


_JOB_PATTERN = re.compile(
    r"""
    ^JOB[ \t]+(?P<name>\S+)
    [ \t]+AT[ \t]+(?P<at>\d{2}:\d{2})
    [ \t]+RUN[ \t]+(?P<script>\S+)
    (?:[ \t]+ON_ERROR[ \t]+
        (?P<error>ABORT|CONTINUE|RETRY:(?P<retries>\d+))
    )?
    $
    """,
    re.VERBOSE,
)


def parse_schedule(cfg_text: str) -> list[dict]:
    """Parse a Meridian CRM batch schedule into modern schedule entries."""
    schedule = []

    for line_number, raw_line in enumerate(cfg_text.splitlines(), start=1):
        line = raw_line.strip()

        if not line or line.startswith("#"):
            continue

        match = _JOB_PATTERN.fullmatch(line)
        if match is None:
            raise ValueError(f"Invalid schedule line {line_number}: {raw_line!r}")

        hour, minute = map(int, match.group("at").split(":"))
        if hour > 23 or minute > 59:
            raise ValueError(f"Invalid time on line {line_number}: {match.group('at')!r}")

        error_clause = match.group("error")
        if error_clause is None or error_clause == "ABORT":
            policy = "ABORT"
            retries = 0
        elif error_clause == "CONTINUE":
            policy = "CONTINUE"
            retries = 0
        else:
            policy = "RETRY"
            retries = int(match.group("retries"))

        schedule.append(
            {
                "name": match.group("name"),
                "at": match.group("at"),
                "script": match.group("script"),
                "on_error": {
                    "policy": policy,
                    "retries": retries,
                },
            }
        )

    return schedule
